// Does the lookahead that skips whitespace before an enclosure cross a NEWLINE?
$cases = [
    " \n\"a\"\n",
    "a, \n\"b\"\n",
    " \r\n\"a\"\n",
];
foreach ($cases as $i => $text) {
    $h = fopen("php://memory", "w+");
    fwrite($h, $text);
    rewind($h);
    echo "stream case $i\n";
    while (($row = fgetcsv($h, 0, ",", "\"", "\\")) !== false) {
        var_dump($row);
    }
    fclose($h);
    echo "string case $i\n";
    var_dump(str_getcsv(rtrim($text, "\n"), ",", "\"", "\\"));
}
